// s5_expr.js - Expression evaluator with + - * / and ^ operations

function evaluate(expr) {
    // Remove all spaces
    expr = expr.replace(/\s/g, '');

    // Check for empty expression
    if (expr === '') {
        throw new Error('Empty expression');
    }

    // Check for invalid characters - allow numbers, +, -, *, /, ^, ., (, )
    if (!/^[0-9+\-*/^.()]+$/.test(expr)) {
        throw new Error('Invalid characters in expression');
    }

    // Handle division by zero
    if (expr.match(/\/0(?:\.0*)?/)) {
        throw new Error('Division by zero');
    }

    // Parse and evaluate expression with proper precedence
    try {
        // Tokenize the expression
        const tokens = tokenize(expr);
        // Parse and evaluate
        const result = parseExpression(tokens, 0);

        if (typeof result !== 'number' || isNaN(result)) {
            throw new Error('Invalid expression');
        }

        return result;
    } catch (e) {
        throw new Error('Invalid expression');
    }
}

// Tokenizer function
function tokenize(expr) {
    const tokens = [];
    let i = 0;

    while (i < expr.length) {
        const char = expr[i];

        if (/\d/.test(char)) {
            // Parse number (including decimals)
            let num = '';
            while (i < expr.length && (/\d/.test(expr[i]) || expr[i] === '.')) {
                num += expr[i];
                i++;
            }
            tokens.push({ type: 'number', value: parseFloat(num) });
            continue;
        }

        if (char === '+' || char === '-' || char === '*' || char === '/' || char === '^' || char === '(' || char === ')') {
            tokens.push({ type: char, value: char });
        } else {
            throw new Error('Invalid character: ' + char);
        }

        i++;
    }

    return tokens;
}

// Recursive descent parser with precedence
function parseExpression(tokens, pos) {
    // Parse left operand
    let left = parsePower(tokens, pos);

    // Look for operators
    while (pos < tokens.length && (tokens[pos].type === '+' || tokens[pos].type === '-')) {
        const op = tokens[pos].type;
        pos++;
        const right = parsePower(tokens, pos);
        if (op === '+') {
            left = left + right;
        } else {
            left = left - right;
        }
    }

    return left;
}

// Parse power operator with right associativity
function parsePower(tokens, pos) {
    let left = parseFactor(tokens, pos);

    // Look for power operator
    if (pos < tokens.length && tokens[pos].type === '^') {
        pos++;
        // For right associativity, we parse the right side with higher precedence
        const right = parsePower(tokens, pos);
        left = Math.pow(left, right);
    }

    return left;
}

// Parse factors (numbers, parentheses, unary minus)
function parseFactor(tokens, pos) {
    if (pos >= tokens.length) {
        throw new Error('Unexpected end of expression');
    }

    const token = tokens[pos];

    if (token.type === 'number') {
        return token.value;
    }

    if (token.type === '(') {
        // Find matching closing parenthesis
        let parenCount = 1;
        let i = pos + 1;
        while (i < tokens.length && parenCount > 0) {
            if (tokens[i].type === '(') {
                parenCount++;
            } else if (tokens[i].type === ')') {
                parenCount--;
            }
            i++;
        }

        if (parenCount !== 0) {
            throw new Error('Mismatched parentheses');
        }

        // Parse the expression inside parentheses
        const exprResult = parseExpression(tokens, pos + 1);
        return exprResult;
    }

    if (token.type === '-') {
        // Handle unary minus
        pos++;
        const factor = parseFactor(tokens, pos);
        return -factor;
    }

    throw new Error('Unexpected token: ' + token.type);
}
